  const packKey=clean(get('packKey')),packQty=num(get('packQty')),match=packKey.match(/--([0-9]+(?:\.[0-9]+)?)$/),parsedFactor=match?Number(match[1]):0;
  const factor=parsedFactor>1&&Number.isFinite(packQty)&&packQty>=0&&same(packQty*parsedFactor,units)?parsedFactor:null;
  let expiry='';if(clean(get('expiry'))){try{expiry=PressedExcel.isoDate(get('expiry'),sheet.date1904);}catch(_){expiry=clean(get('expiry'));}}
  rows.push({id,client,sku,name:clean(get('name'))||sku,locId:clean(get('locId'))||loc,loc,zone:clean(get('zone')),type:clean(get('type')),lot:clean(get('lot')),expiry,units:round(units),factor,packQty:Number.isFinite(packQty)?packQty:null,packKey,container:clean(get('container'))||clean(get('fallbackContainer')),status:clean(get('status')),seq:Number.isFinite(num(get('seq')))?num(get('seq')):null});
